-- Aztec Mural for Casino El Camino
-- centraltexasmuralsbyroryskagen-20231217234521 · restaurant/aztec-mural-for-casino-el-camino/index.html · kind=mural
INSERT INTO public.artworks (
  slug, title, year, kind, narrative,
  draft, enabled, archived, trashed,
  source_site, source_url_path, source_archive_path,
  metadata
) VALUES (
  'aztec-mural-for-casino-el-camino',
  'Aztec Mural for Casino El Camino',
  '2010',
  'mural',
  'This mural created to finalize the look of the Casino El Camino patio had many challenges. "Casino", the owner, wanted to open up his enclosed patio with "windows" that look out onto an Aztec landscape. The red stucco wall, that matched the tile, already had the skull light sconces in place which we created years earlier. Furthermore, the texture of the wall was such, that we couldn''t just paint the scene convincingly on the wall. Therefore, it was decided we would cut into the wall to create openings for the mural to fit into, creating the illusion of architecture in front of a landscape. The landscape imagery, inspired by 19th century explorer and artist Frederick Catherwood , was painted on wooden panels at the shop using outdoor quality sign paint. During this process, we also had our team cutting into the wall, framing out the openings, and finally match the existing stucco. The wall itself was then painted to resemble an ancient stone wall, matching the rest of the walls in the patio.',
  true,   -- draft: unreviewed client work (R-02)
  false,  -- enabled: must not render anywhere
  false,
  false,
  'centraltexasmurals.com',
  '/restaurant/aztec-mural-for-casino-el-camino/',
  'centraltexasmuralsbyroryskagen-20231217234521',
  jsonb_build_object(
    'wayback', jsonb_build_object(
      'archive', 'centraltexasmuralsbyroryskagen-20231217234521',
      'relPath', 'restaurant/aztec-mural-for-casino-el-camino/index.html',
      'categories', jsonb_build_array('Restaurant'),
      'description', '',
      'wpPostId', '62',
      'publishedAt', '2010-03-19 16:16:38'
    )
  )
)
ON CONFLICT (slug) DO NOTHING;

