-- Rooster Teeth Mural
-- centraltexasmuralsbyroryskagen-20231217234521 · business/rooster-teeth-mural/index.html · kind=mural
INSERT INTO public.artworks (
  slug, title, year, kind, narrative,
  draft, enabled, archived, trashed,
  source_site, source_url_path, source_archive_path,
  metadata
) VALUES (
  'rooster-teeth-mural',
  'Rooster Teeth Mural',
  '2011',
  'mural',
  'The incredible guys at roosterteeth.com asked us to design and create this mural about consumerism and politics for their new office in downtown Austin. The 8'' x 32'' mural was painted on 8 panels and installed at their location. The Latin phrase above the mural reads Laboris Voro Ingemino , which roughly translated means: "work hard, consume, continue with increased effort". They came to us with a general concept and we worked out the composition. The sayings on the mural were provided by Roosterteeth. Seems they understand capitalism, better than most.',
  true,   -- draft: unreviewed client work (R-02)
  false,  -- enabled: must not render anywhere
  false,
  false,
  'centraltexasmurals.com',
